// ACT3: 海砂漠
INFO_STATUS_KEYS.push('激流','砂塵','脱力');
Object.assign(keywords,{'激流':'ターン終了時に7ダメージを受け、激流1を失う。','砂塵':'付与された次のターンから、ターン開始時に手札からカード1枚を選んで捨て、砂塵1を失う。','脱力':'与えるダメージが30%減少する。ターン終了時に脱力1を失う。'});
const desertArtBase=destinationArt;destinationArt=function(id){if(id!==3)return desertArtBase(id);return '<svg viewBox="0 0 700 540" role="img" aria-label="海砂漠の砂丘と海の生き物"><defs><linearGradient id="desertSky" x2="0" y2="1"><stop stop-color="#243c46"/><stop offset="1" stop-color="#c5a46e"/></linearGradient></defs><rect width="700" height="540" fill="url(#desertSky)"/><circle cx="520" cy="116" r="66" fill="#f3d498" opacity=".35"/><path d="M0 335Q155 215 335 345T700 290V540H0Z" fill="#aa895d"/><path d="M0 415Q185 310 370 409T700 360V540H0Z" fill="#856d4c"/><path d="M0 485Q185 380 400 470T700 435V540H0Z" fill="#514c3c"/><path d="M175 290Q260 225 350 267Q384 252 412 263L390 282Q325 320 263 293L218 313Z" fill="#263c3b" opacity=".8"/><path d="M239 289L208 325 262 303M308 264L322 242 337 266" fill="#263c3b"/></svg>';};
const DESERT_FOES={star:['乾燥ヒトデ','✶',40,[{sand:1},{d:7,weak:1},{b:7}]],jelly:['漂う海月','♧',60,[{d:3,h:3},{torrent:2},{s:1}]],crab:['盾蟹','♜',24,[{b:5},{torrent:3},{d:2,h:3},{d:7},{s:1}]],snake:['砂舞蛇','♒',50,[{s:1},{d:8},{d:4,h:2},{b:5}]],shrimp:['粉砕シャコ','⚒',80,[{d:10},{d:5,h:3},{d:20},{d:3,h:5}]],squid:['渦巻くイカ','♆',66,[{torrent:1},{d:15},{b:10},{heal:6},{torrentUp:1}]],whale:['砂鯨','◒',70,[{sand:2},{d:10},{sand:2,b:10},{d:5,h:3},{s:2}]],mother:['ハハナルタツ','♞',150,[{heal:20},{d:12},{d:6,h:2,s:2},{b:10},{torrent:6},{birth:true}]],child:['オトシゴ','♘',200,[{d:5,h:3},{torrent:2},{d:7,h:3},{b:20},{d:20},{torrentUp:1}]]};
function desertFoe(key,offset=0){const [name,icon,hp]=DESERT_FOES[key],e=Object.assign(enemy(name,icon,hp,0),{act2:true,act3:true,desertKey:key,actionStep:offset,str:0});if(key==='crab'){e.plate=7;e.retainBlock=true;}return e;}
function desertEncounter(r,type){if(type==='boss')return [desertFoe('mother')];if(type==='elite'){r.desertElitePool??=[];if(!r.desertElitePool.length)r.desertElitePool=shuffle(['shrimp','squid','whale']);return [desertFoe(r.desertElitePool.pop())];}r.desertFights=(r.desertFights||0)+1;return rand(r.desertFights<=3?[()=>[desertFoe('star')],()=>[desertFoe('jelly')],()=>[desertFoe('crab')],()=>[desertFoe('snake')]]:[()=>[desertFoe('star'),desertFoe('crab')],()=>[desertFoe('jelly'),desertFoe('star')],()=>[desertFoe('snake'),desertFoe('crab')],()=>[desertFoe('star'),desertFoe('star'),desertFoe('snake')]])();}
function planDesert(r){for(const e of r.enemies||[]){if(!e.act3||e.hp<=0)continue;const list=DESERT_FOES[e.desertKey][3];if(e.desertKey==='mother'&&e.actionStep%6===5&&(e.growth||0)<10)e.actionStep++;let a={...list[e.actionStep%list.length]};if(a.torrent)a.torrent+=(e.torrentBonus||0);e.snowAction=a;e.intent=a.d!=null?'attack':a.b?'guard':'snowAction';e.atk=a.d||0;e.hits=a.h||1;e.guardAmount=a.b||0;if(e.hunterStun||e.birthStun>0)e.intent='stunned';if(e.desertStartTurn!==r.turn){e.desertStartTurn=r.turn;if(e.plate>0){e.block=(e.block||0)+e.plate;e.plate--;}}}}
function desertBirth(r,e){if(e.birthDone)return;e.birthDone=true;const count=e.growth||0,child=desertFoe('child');child.max=child.hp=200+count*10;child.birthStun=2;if(r.enemyPhase)child.summonedTurn=r.turn;r.enemies.push(child);r.torrent=(r.torrent||0)+count;planDesert(r);}
const desertChooseBase=choose;choose=function(type){const r=S.run,old=r?.mode;desertChooseBase(type);if(r===S.run&&r?.act===3&&old!=='battle'&&r.mode==='battle'&&['fight','elite','boss'].includes(type)){r.torrent=0;r.sand=0;r.weak=0;r.enemies=desertEncounter(r,type);if(r.enemies.some(e=>e.desertKey==='snake'))r.sand+=5;target=0;healthVisuals.clear();planDesert(r);render();}};
const desertPlanBase=prepareEncounterTurn;prepareEncounterTurn=function(r){desertPlanBase(r);if(r.act===3)planDesert(r);};
const desertBossBase=bossPlan;bossPlan=function(r){if(r.act===3){planDesert(r);return;}return desertBossBase(r);};
const desertActionBase=snowAction;snowAction=function(r,e){if(!e.act3)return desertActionBase(r,e);const a=e.snowAction||{};if(a.torrent)r.torrent=(r.torrent||0)+a.torrent;if(a.sand)r.sand=(r.sand||0)+a.sand;if(a.weak)r.weak=(r.weak||0)+a.weak;if(a.s)e.str=(e.str||0)+a.s;if(a.heal)healHP(e,a.heal);if(a.torrentUp)e.torrentBonus=(e.torrentBonus||0)+a.torrentUp;if(a.birth){e.hp=0;desertBirth(r,e);}};
const desertActionEndBase=hunterEnemyActionEnd;hunterEnemyActionEnd=function(r,e){desertActionEndBase(r,e);if(!e.act3)return;if(e.desertKey==='mother'&&e.hp>0){e.growth=(e.growth||0)+1;e.str=(e.str||0)+1;}if(e.birthStun>0)e.birthStun--;if(e.springStrength){e.str=Math.max(0,(e.str||0)-e.springStrength);e.springStrength=0;}e.weak=Math.max(0,(e.weak||0)-1);};
const desertTurnEndBase=hunterPlayerTurnEnd;hunterPlayerTurnEnd=function(r){desertTurnEndBase(r);if(r.torrent>0){const extra=r.enemies.some(e=>e.hp>0&&e.desertKey==='squid')?r.torrent:0;dealDamage(r,7+extra,{damageKind:'激流'});r.torrent--;}r.weak=Math.max(0,(r.weak||0)-1);};
const desertDamageBase=dealDamage;dealDamage=function(e,n,options={}){const r=S.run,attacker=options.attacker;if(attacker?.weak)n=Math.floor(n*.7);const alive=e?.hp>0,lost=desertDamageBase(e,n,options);if(e?.act3&&e.desertKey==='shrimp'&&options.attack&&e.hp>0){e.str=(e.str||0)+1;e.springStrength=(e.springStrength||0)+1;}if(alive&&e?.act3&&e.desertKey==='mother'&&e.hp<=0)desertBirth(r,e);return lost;};
const desertStartSand=new WeakMap();
const desertStartBase=applyTurnStartBuffs;applyTurnStartBuffs=function(r){desertStartSand.set(r,{turn:r.turn,eligible:r.sand>0});return desertStartBase(r);};
const desertEndBase=endTurn;endTurn=async function(){const r=S.run,turn=r?.turn;await desertEndBase();if(S.run!==r||r?.act!==3||r.mode!=='battle'||r.turn===turn||r.hp<=0)return;const start=desertStartSand.get(r);if(start?.turn===r.turn&&start.eligible&&r.sand>0){r.sand--;if(r.hand.length)r.pendingChoice={kind:'discard',remaining:1,desertSand:true};}render();};
const desertHandBase=chooseHand;chooseHand=function(i){const r=S.run;if(!r?.pendingChoice?.desertSand)return desertHandBase(i);if(busy||i<0||i>=r.hand.length)return;r.discard.push(r.hand.splice(i,1)[0]);r.pendingChoice=null;for(const e of r.enemies)if(e.hp>0&&e.desertKey==='whale')e.str=(e.str||0)+1;render();};
const desertIntentBase=intent;intent=function(e){if(!e.act3)return desertIntentBase(e);if(e.intent==='stunned')return '<strong>⏸ スタン</strong><small>行動不能</small>';const a=e.snowAction||{};return [a.d?'<strong>⚔ '+enemyAttack(e)+(a.h>1?' × '+a.h:'')+'</strong>':'',a.b?'<strong>◇ '+a.b+'</strong>':'',a.torrent?intentStatus('激流',a.torrent):'',a.sand?intentStatus('砂塵',a.sand):'',a.weak?intentStatus('脱力',a.weak):'',a.s?intentStatus('筋力','+'+a.s):'',a.heal?'<strong>回復 '+a.heal+'</strong>':'',a.torrentUp?'<strong>激流付与量 +'+a.torrentUp+'</strong>':'',a.birth?'<strong>新たなる生命</strong>':''].join('');};
const desertAbilityBase=enemyAbilities;enemyAbilities=function(e){if(!e.act3)return desertAbilityBase(e);const map={crab:[['鉄壁','ターン開始時、ブロックを失わない。']],snake:[['砂風','戦闘開始時、砂塵5を与える。']],shrimp:[['ばね力','攻撃を受けるたび、そのターンの間筋力1を得る。']],squid:[['渦潮','激流は追加で激流1につき1ダメージを与える。']],whale:[['砂の噴出','プレイヤーが砂塵でカードを捨てるたび、筋力1を得る。']],mother:[['新たなる生命','死亡時、何かを産み落とす。'],['成長する生命 '+(e.growth||0),'ターン終了時、カウントと筋力を1得る。']],child:[['誕生','ハハナルタツの成長カウント1につき、最大HPを10得る。'],['産声','ハハナルタツの成長カウント1につき、激流1を与える。']]};return map[e.desertKey]||[];};
const desertAbilitiesHTMLBase=enemyAbilitiesHTML;enemyAbilitiesHTML=function(e){let html=desertAbilitiesHTMLBase(e);return e.act3&&['mother','child'].includes(e.desertKey)?html.replace('enemy-abilities ', 'enemy-abilities boss-abilities '):html;};
const desertBattleBase=battle;battle=function(){let html=desertBattleBase(),r=S.run;if(r.act!==3)return html;let statuses=[['torrent','激流'],['sand','砂塵'],['weak','脱力']].map(([k,n])=>r[k]?statusEffectHTML(n,r[k]):'').join('');return html.replace('<div class="player-status">','<div class="player-status">'+statuses).replace(/<h2>[^<]*<\/h2>/,'<h2>'+(r.kind==='boss'?'海砂漠の主':r.kind==='elite'?'海砂漠の強敵':'海砂漠')+'</h2>');};
const desertVictoryBase=victory;victory=function(){if(S.run?.act===3&&S.run.enemies?.every(e=>e.hp<=0)){S.run.torrent=0;S.run.sand=0;S.run.weak=0;}return desertVictoryBase();};
if(!globalThis.ASHBOUND_HEADLESS)render();
